SysDataModelXML.SQLScript:
DECLARE @MFGNUM VARCHAR(30) = '{0}' DECLARE @MFBLIN INT = 0{1}; DECLARE @YARNGRP VARCHAR(30) = '{2}';
-- 累计克重 DECLARE @TOLKZ DECIMAL(18, 2);
SELECT @TOLKZ = SUM(GRPQTY * GRPBAS) FROM MFGOPD WHERE MFGNUM = @MFGNUM AND MFBLIN = @MFBLIN AND YARNGRP = @YARNGRP AND OPDTYP = 'MATGRP';
-- 未填写条子克重时 IF @TOLKZ = 0 SET @TOLKZ = 160;
WITH CTE_MAT AS ( SELECT M.MFMLIN , CONCAT_WS(' ', M.CPNITMVER, M.CPNLOT, M.CPNSUBLOT) AS MFMDES , M.CPNITMVER MFMSHO -- , M.CPNITMNO -- , I.ITMNAM + I.ITMNAM1 ITMNAM -- , M.CPNITMVER -- , M.CPNLOT -- , M.CPNSUBLOT , CAST(M.MATRAT AS DECIMAL(18, 2)) MATRAT , ISNULL(M.MATRATHY, 0) MATRATHY -- , M.MATRAT - ISNULL(M.MATRATHY, 0) - CAST(ISNULL(D.GRPBAS, 0) * ISNULL(M.TDGS, 0) / @TOLKZ * 100 AS DECIMAL(18, 6)) MATRATGY , CAST(ISNULL(D.GRPBAS, 0) * ISNULL(M.TDGS, 0) / @TOLKZ * 100 AS DECIMAL(18, 6)) MATRATTD , M.MATPOS POSITION FROM MFGMAT M LEFT JOIN ITM I ON M.CPNITMNO = I.ITMNO LEFT JOIN MFGOPD D ON M.MFGNUM = D.MFGNUM AND M.MFBLIN = D.MFBLIN AND M.YARNGRP = D.YARNGRP AND M.OPECOD = D.OPECOD -- AND D.OPECOD <> '0' AND D.OPDTYP = 'MATGRP' WHERE M.MFGNUM = @MFGNUM AND M.MFBLIN = @MFBLIN AND M.YARNGRP = @YARNGRP ) , CTE_GY AS ( SELECT MFMLIN , MFMDES , MFMSHO , M.MATRAT - M.MATRATHY - M.MATRATTD MATRATCALC , POSITION FROM CTE_MAT M WHERE M.MATRAT - M.MATRATHY - M.MATRATTD > 0 ) , CTE_CALC AS ( SELECT * FROM CTE_GY
UNION ALL
-- HY条子 SELECT 99999 MFMLIN , 'HY 条子' MFMDES , 'HY 条子' MFMSHO , SUM(MATRATHY) MATRATCALC , '' POSITION FROM CTE_MAT M WHERE M.MATRATHY > 0 ) SELECT MFMLIN , MFMDES , MFMSHO , MATRATCALC , CAST(0 AS INT) PRIORITY , ISNULL(POSITION, '') POSITION FROM CTE_CALC WHERE MATRATCALC > 0 ORDER BY MFMLIN
